arguments.command:
cd /workspace/submission && grep -n "print(" main.py; python3 -m py_compile main.py && echo "compiles OK"; find /workspace/submission -mindepth 1 | sort; python3 - <<'PYEOF'
import ast, sys
tree = ast.parse(open('/workspace/submission/main.py').read())
defined = set()
for node in ast.walk(tree):
    if isinstance(node, (ast.FunctionDef, ast.ClassDef)):
        defined.add(node.name)
    if isinstance(node, ast.Assign):
        for t in node.targets:
            if isinstance(t, ast.Name): defined.add(t.id)
used = {n.id for n in ast.walk(tree) if isinstance(n, ast.Name) and isinstance(n.ctx, ast.Load)}
used |= {n.attr for n in ast.walk(tree) if isinstance(n, ast.Attribute)}
unused = sorted(d for d in defined if d not in used and not d.startswith('__'))
print("possibly unused names:", unused)
PYEOF
rm -rf /workspace/submission/__pycache__ 2>/dev/null; find /workspace/submission -mindepth 1 | sort
